-- Section 8 schema clean-up, platform domain (docs/POSTGRES_CUTOVER_REPORT.md §8).
-- Every conversion is guarded: if any existing row holds a value outside the
-- target set, the migration stops and names the values instead of guessing.

DO $$
DECLARE bad text;
BEGIN
  SELECT string_agg(DISTINCT COALESCE("status"::text, 'NULL'), ', ') INTO bad FROM "DomainEventOutbox" WHERE "status" NOT IN ('PENDING', 'PROCESSING', 'PROCESSED', 'RETRY', 'DEAD_LETTER');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'DomainEventOutbox.status holds values outside DomainEventOutboxStatus: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("status"::text, 'NULL'), ', ') INTO bad FROM "DomainEventDelivery" WHERE "status" NOT IN ('PENDING', 'PROCESSED', 'FAILED', 'DEAD_LETTER');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'DomainEventDelivery.status holds values outside DomainEventDeliveryStatus: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("status"::text, 'NULL'), ', ') INTO bad FROM "WorkflowDefinition" WHERE "status" NOT IN ('ACTIVE', 'INACTIVE');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'WorkflowDefinition.status holds values outside WorkflowDefinitionStatus: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("status"::text, 'NULL'), ', ') INTO bad FROM "WorkflowVersion" WHERE "status" NOT IN ('DRAFT', 'PUBLISHED', 'RETIRED');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'WorkflowVersion.status holds values outside WorkflowVersionStatus: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("status"::text, 'NULL'), ', ') INTO bad FROM "WorkflowInstance" WHERE "status" NOT IN ('RUNNABLE', 'RUNNING', 'WAITING', 'COMPLETED', 'FAILED', 'CANCELLED');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'WorkflowInstance.status holds values outside WorkflowInstanceStatus: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("stepType"::text, 'NULL'), ', ') INTO bad FROM "WorkflowStep" WHERE "stepType" NOT IN ('CONDITION', 'ACTION', 'TASK', 'TIMER');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'WorkflowStep.stepType holds values outside the allowed set: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("status"::text, 'NULL'), ', ') INTO bad FROM "WorkflowStep" WHERE "status" NOT IN ('PENDING', 'RUNNING', 'WAITING', 'COMPLETED', 'SKIPPED', 'FAILED');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'WorkflowStep.status holds values outside WorkflowStepStatus: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("priority"::text, 'NULL'), ', ') INTO bad FROM "WorkflowTask" WHERE "priority" NOT IN ('ROUTINE', 'URGENT', 'STAT');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'WorkflowTask.priority holds values outside Priority: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("status"::text, 'NULL'), ', ') INTO bad FROM "WorkflowTask" WHERE "status" NOT IN ('OPEN', 'IN_PROGRESS', 'COMPLETED', 'CANCELLED', 'EXPIRED');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'WorkflowTask.status holds values outside WorkflowTaskStatus: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("kind"::text, 'NULL'), ', ') INTO bad FROM "WorkflowTimer" WHERE "kind" NOT IN ('DELAY', 'SLA');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'WorkflowTimer.kind holds values outside the allowed set: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("status"::text, 'NULL'), ', ') INTO bad FROM "WorkflowTimer" WHERE "status" NOT IN ('PENDING', 'CLAIMED', 'COMPLETED', 'CANCELLED');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'WorkflowTimer.status holds values outside WorkflowTimerStatus: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("scope"::text, 'NULL'), ', ') INTO bad FROM "ConfigurationOverride" WHERE "scope" NOT IN ('ORGANIZATION', 'FACILITY', 'DEPARTMENT');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'ConfigurationOverride.scope holds values outside ConfigurationOverrideScope: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("status"::text, 'NULL'), ', ') INTO bad FROM "ConfigurationOverride" WHERE "status" NOT IN ('DRAFT', 'PUBLISHED', 'RETIRED');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'ConfigurationOverride.status holds values outside ConfigurationOverrideStatus: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("action"::text, 'NULL'), ', ') INTO bad FROM "ConfigurationChange" WHERE "action" NOT IN ('SET', 'PUBLISH', 'RESET', 'RETIRE');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'ConfigurationChange.action holds values outside ConfigurationChangeAction: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("status"::text, 'NULL'), ', ') INTO bad FROM "WorkflowBuilderDraft" WHERE "status" NOT IN ('DRAFT');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'WorkflowBuilderDraft.status holds values outside WorkflowBuilderDraftStatus: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("entityType"::text, 'NULL'), ', ') INTO bad FROM "ExternalIdentifier" WHERE "entityType" NOT IN ('PATIENT', 'FACILITY', 'STAFF', 'ENCOUNTER', 'ORGANIZATION', 'DOCUMENT');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'ExternalIdentifier.entityType holds values outside the allowed set: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("use"::text, 'NULL'), ', ') INTO bad FROM "ExternalIdentifier" WHERE "use" NOT IN ('OFFICIAL', 'SECONDARY', 'OLD');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'ExternalIdentifier.use holds values outside ExternalIdentifierUse: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("status"::text, 'NULL'), ', ') INTO bad FROM "ExternalIdentifier" WHERE "status" NOT IN ('ACTIVE', 'SUPERSEDED', 'REVOKED', 'INVALID');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'ExternalIdentifier.status holds values outside ExternalIdentifierStatus: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("source"::text, 'NULL'), ', ') INTO bad FROM "ExternalIdentifier" WHERE "source" NOT IN ('LOCAL_ENTRY', 'REGISTRY_LOOKUP', 'IMPORTED');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'ExternalIdentifier.source holds values outside the allowed set: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("verificationStatus"::text, 'NULL'), ', ') INTO bad FROM "ExternalIdentifier" WHERE "verificationStatus" NOT IN ('UNVERIFIED', 'VERIFIED', 'FAILED');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'ExternalIdentifier.verificationStatus holds values outside ExternalIdentifierVerificationStatus: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("status"::text, 'NULL'), ', ') INTO bad FROM "InteropConsent" WHERE "status" NOT IN ('REQUESTED', 'GRANTED', 'ACTIVE', 'EXPIRED', 'REVOKED', 'DECLINED', 'CANCELLED');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'InteropConsent.status holds values outside InteropConsentStatus: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("recipientType"::text, 'NULL'), ', ') INTO bad FROM "InteropConsent" WHERE "recipientType" NOT IN ('FACILITY', 'ORGANIZATION', 'PRACTITIONER', 'PATIENT', 'EXTERNAL_SYSTEM');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'InteropConsent.recipientType holds values outside the allowed set: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("source"::text, 'NULL'), ', ') INTO bad FROM "InteropConsent" WHERE "source" NOT IN ('LOCAL', 'ABDM');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'InteropConsent.source holds values outside the allowed set: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("direction"::text, 'NULL'), ', ') INTO bad FROM "HealthInformationExchange" WHERE "direction" NOT IN ('OUTBOUND', 'INBOUND');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'HealthInformationExchange.direction holds values outside ExchangeDirection: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("status"::text, 'NULL'), ', ') INTO bad FROM "HealthInformationExchange" WHERE "status" NOT IN ('REQUESTED', 'AUTHORIZED', 'PROCESSING', 'COMPLETED', 'REJECTED', 'FAILED', 'CANCELLED');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'HealthInformationExchange.status holds values outside HealthInformationExchangeStatus: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("direction"::text, 'NULL'), ', ') INTO bad FROM "InteropProvenance" WHERE "direction" NOT IN ('OUTBOUND', 'INBOUND');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'InteropProvenance.direction holds values outside ExchangeDirection: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("dataOrigin"::text, 'NULL'), ', ') INTO bad FROM "InteropProvenance" WHERE "dataOrigin" NOT IN ('LOCAL', 'EXTERNAL', 'IMPORTED', 'MAPPED', 'DERIVED');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'InteropProvenance.dataOrigin holds values outside the allowed set: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("status"::text, 'NULL'), ', ') INTO bad FROM "ImportedResource" WHERE "status" NOT IN ('RECEIVED', 'MAPPED', 'IMPORTED', 'REJECTED', 'CONFLICT');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'ImportedResource.status holds values outside ImportedResourceStatus: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("domain"::text, 'NULL'), ', ') INTO bad FROM "TerminologyMapping" WHERE "domain" NOT IN ('DIAGNOSIS', 'LAB', 'MEDICATION', 'OBSERVATION', 'PROCEDURE', 'UNIT');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'TerminologyMapping.domain holds values outside the allowed set: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("status"::text, 'NULL'), ', ') INTO bad FROM "TerminologyMapping" WHERE "status" NOT IN ('ACTIVE', 'RETIRED');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'TerminologyMapping.status holds values outside TerminologyMappingStatus: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("system"::text, 'NULL'), ', ') INTO bad FROM "InteropConnection" WHERE "system" NOT IN ('ABDM', 'HFR', 'HPR', 'NHCX', 'FHIR');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'InteropConnection.system holds values outside the allowed set: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("environment"::text, 'NULL'), ', ') INTO bad FROM "InteropConnection" WHERE "environment" NOT IN ('DISABLED', 'LOCAL', 'SANDBOX', 'PRODUCTION');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'InteropConnection.environment holds values outside IntegrationEnvironment: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("status"::text, 'NULL'), ', ') INTO bad FROM "InteropConnection" WHERE "status" NOT IN ('NOT_CONFIGURED', 'CONFIGURED', 'ERROR');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'InteropConnection.status holds values outside InteropConnectionStatus: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("role"::text, 'NULL'), ', ') INTO bad FROM "IntegrationCertificate" WHERE "role" NOT IN ('CURRENT', 'NEXT');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'IntegrationCertificate.role holds values outside IntegrationCertificateRole: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("status"::text, 'NULL'), ', ') INTO bad FROM "IntegrationCertificate" WHERE "status" NOT IN ('NOT_CONFIGURED', 'VALID', 'EXPIRING', 'EXPIRED', 'INVALID');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'IntegrationCertificate.status holds values outside IntegrationCertificateStatus: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("environment"::text, 'NULL'), ', ') INTO bad FROM "ExternalParticipant" WHERE "environment" NOT IN ('DISABLED', 'LOCAL', 'SANDBOX', 'PRODUCTION');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'ExternalParticipant.environment holds values outside IntegrationEnvironment: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("status"::text, 'NULL'), ', ') INTO bad FROM "ExternalParticipant" WHERE "status" NOT IN ('ACTIVE', 'INACTIVE');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'ExternalParticipant.status holds values outside ExternalParticipantStatus: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("trustStatus"::text, 'NULL'), ', ') INTO bad FROM "ExternalParticipant" WHERE "trustStatus" NOT IN ('UNVERIFIED', 'VERIFIED', 'SUSPENDED', 'REVOKED');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'ExternalParticipant.trustStatus holds values outside ExternalParticipantTrustStatus: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("severity"::text, 'NULL'), ', ') INTO bad FROM "IntegrationAlert" WHERE "severity" NOT IN ('INFO', 'WARNING', 'CRITICAL');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'IntegrationAlert.severity holds values outside AlertSeverity: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("status"::text, 'NULL'), ', ') INTO bad FROM "IntegrationAlert" WHERE "status" NOT IN ('OPEN', 'ACKNOWLEDGED', 'RESOLVED');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'IntegrationAlert.status holds values outside IntegrationAlertStatus: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("status"::text, 'NULL'), ', ') INTO bad FROM "AbdmCallbackEvent" WHERE "status" NOT IN ('ACCEPTED', 'REJECTED', 'DUPLICATE', 'UNMATCHED');
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'AbdmCallbackEvent.status holds values outside AbdmCallbackEventStatus: %; resolve before migrating', bad; END IF;
  SELECT string_agg(DISTINCT COALESCE("facilityId"::text, 'NULL'), ', ') INTO bad FROM "HealthInformationExchange" WHERE "facilityId" IS NULL AND "idempotencyKey" IS NOT NULL;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'HealthInformationExchange.facilityId holds values outside a tenant (facilityId) for every keyed row: %; resolve before migrating', bad; END IF;
END $$;

